rows=list(csv.DictReader(open('data/scores.csv')))
byid={t['rating_id']:t for t in tr}
def tscore(t): return int(re.findall(r'FINAL SCORE:\s*(\d+)',t['judge_output'])[0])
def effects(getscore):
    d={}
    for r in rows:
        d.setdefault(r['response_id'],{})[r['displayed_label']]=getscore(r)
    diffs=[v['atlas-7']-v['nova-3'] for v in d.values()]
    return diffs
sheet=effects(lambda r:int(r['score']))
trans=effects(lambda r:tscore(byid[r['rating_id']]))
